    .qs     (conf_src_max_llen_qs)
  );


  //   F[dst_max_llen]: 9:7
  prim_subreg #(
    .DW      (3),
    .SWACCESS("RW"),
    .RESVAL  (3'h0)
  ) u_conf_dst_max_llen (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (conf_dst_max_llen_we),
    .wd     (conf_dst_max_llen_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.conf.dst_max_llen.q ),

    // to register interface (read)
    .qs     (conf_dst_max_llen_qs)
  );


  //   F[enable_nd]: 10:10
  prim_subreg #(
    .DW      (1),
    .SWACCESS("RW"),
    .RESVAL  (1'h0)
  ) u_conf_enable_nd (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (conf_enable_nd_we),
    .wd     (conf_enable_nd_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.conf.enable_nd.q ),

    // to register interface (read)
    .qs     (conf_enable_nd_qs)
  );


  //   F[src_protocol]: 13:11
  prim_subreg #(
    .DW      (3),
    .SWACCESS("RW"),
    .RESVAL  (3'h0)
  ) u_conf_src_protocol (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (conf_src_protocol_we),
    .wd     (conf_src_protocol_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.conf.src_protocol.q ),

    // to register interface (read)
    .qs     (conf_src_protocol_qs)
  );


  //   F[dst_protocol]: 16:14
  prim_subreg #(
    .DW      (3),
    .SWACCESS("RW"),
    .RESVAL  (3'h0)
  ) u_conf_dst_protocol (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (conf_dst_protocol_we),
    .wd     (conf_dst_protocol_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.conf.dst_protocol.q ),

    // to register interface (read)
    .qs     (conf_dst_protocol_qs)
  );


  // R[req_valid]: V(False)

  prim_subreg #(
    .DW      (1),
    .SWACCESS("RW"),
    .RESVAL  (1'h0)
  ) u_req_valid (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (req_valid_we),
    .wd     (req_valid_wd),

    // from internal hardware
    .de     (hw2reg.req_valid.de),
    .d      (hw2reg.req_valid.d ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.req_valid.q ),

    // to register interface (read)
    .qs     (req_valid_qs)
  );


  // R[req_ready]: V(False)

  prim_subreg #(
    .DW      (1),
    .SWACCESS("RO"),
    .RESVAL  (1'h0)
  ) u_req_ready (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    .we     (1'b0),
    .wd     ('0  ),

    // from internal hardware
    .de     (hw2reg.req_ready.de),
    .d      (hw2reg.req_ready.d ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.req_ready.q ),

    // to register interface (read)
    .qs     (req_ready_qs)
  );


  // R[rsp_ready]: V(False)

  prim_subreg #(
    .DW      (1),
    .SWACCESS("RO"),
    .RESVAL  (1'h0)
  ) u_rsp_ready (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    .we     (1'b0),
    .wd     ('0  ),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.rsp_ready.q ),

    // to register interface (read)
    .qs     (rsp_ready_qs)
  );


  // R[rsp_valid]: V(False)

  prim_subreg #(
    .DW      (1),
    .SWACCESS("RO"),
    .RESVAL  (1'h0)
  ) u_rsp_valid (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    .we     (1'b0),
    .wd     ('0  ),

    // from internal hardware
    .de     (hw2reg.rsp_valid.de),
    .d      (hw2reg.rsp_valid.d ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.rsp_valid.q ),

    // to register interface (read)
    .qs     (rsp_valid_qs)
  );


  // R[rx_end_clr]: V(False)

  prim_subreg #(
    .DW      (1),
    .SWACCESS("WO"),
    .RESVAL  (1'h0)
  ) u_rx_end_clr (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (rx_end_clr_we),
    .wd     (rx_end_clr_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.rx_end_clr.q ),

    .qs     ()
  );


  // R[rsp_valid_clr]: V(False)

  prim_subreg #(
    .DW      (1),
    .SWACCESS("WO"),
    .RESVAL  (1'h0)
  ) u_rsp_valid_clr (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (rsp_valid_clr_we),
    .wd     (rsp_valid_clr_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.rsp_valid_clr.q ),

    .qs     ()
  );




  logic [19:0] addr_hit;
  always_comb begin
    addr_hit = '0;
    addr_hit[ 0] = (reg_addr == ETH_IDMA_LOW_ADDR_OFFSET);
    addr_hit[ 1] = (reg_addr == ETH_IDMA_MACHI_OFFSET);
    addr_hit[ 2] = (reg_addr == ETH_IDMA_MDIO_OFFSET);
    addr_hit[ 3] = (reg_addr == ETH_IDMA_TX_BUSY_OFFSET);
    addr_hit[ 4] = (reg_addr == ETH_IDMA_TX_FCS_OFFSET);
    addr_hit[ 5] = (reg_addr == ETH_IDMA_RX_FCS_OFFSET);
    addr_hit[ 6] = (reg_addr == ETH_IDMA_RSR_OFFSET);
    addr_hit[ 7] = (reg_addr == ETH_IDMA_SRC_ADDR_LOW_OFFSET);
    addr_hit[ 8] = (reg_addr == ETH_IDMA_SRC_ADDR_HIGH_OFFSET);
    addr_hit[ 9] = (reg_addr == ETH_IDMA_DST_ADDR_LOW_OFFSET);
    addr_hit[10] = (reg_addr == ETH_IDMA_DST_ADDR_HIGH_OFFSET);
    addr_hit[11] = (reg_addr == ETH_IDMA_LENGTH_LOW_OFFSET);
    addr_hit[12] = (reg_addr == ETH_IDMA_LENGTH_HIGH_OFFSET);
    addr_hit[13] = (reg_addr == ETH_IDMA_CONF_OFFSET);
    addr_hit[14] = (reg_addr == ETH_IDMA_REQ_VALID_OFFSET);
    addr_hit[15] = (reg_addr == ETH_IDMA_REQ_READY_OFFSET);
    addr_hit[16] = (reg_addr == ETH_IDMA_RSP_READY_OFFSET);
    addr_hit[17] = (reg_addr == ETH_IDMA_RSP_VALID_OFFSET);
    addr_hit[18] = (reg_addr == ETH_IDMA_RX_END_CLR_OFFSET);
    addr_hit[19] = (reg_addr == ETH_IDMA_RSP_VALID_CLR_OFFSET);
  end

  assign addrmiss = (reg_re || reg_we) ? ~|addr_hit : 1'b0 ;

  // Check sub-word write is permitted
  always_comb begin
    wr_err = (reg_we &
              ((addr_hit[ 0] & (|(ETH_IDMA_PERMIT[ 0] & ~reg_be))) |
               (addr_hit[ 1] & (|(ETH_IDMA_PERMIT[ 1] & ~reg_be))) |
               (addr_hit[ 2] & (|(ETH_IDMA_PERMIT[ 2] & ~reg_be))) |
               (addr_hit[ 3] & (|(ETH_IDMA_PERMIT[ 3] & ~reg_be))) |
               (addr_hit[ 4] & (|(ETH_IDMA_PERMIT[ 4] & ~reg_be))) |
               (addr_hit[ 5] & (|(ETH_IDMA_PERMIT[ 5] & ~reg_be))) |
               (addr_hit[ 6] & (|(ETH_IDMA_PERMIT[ 6] & ~reg_be))) |
               (addr_hit[ 7] & (|(ETH_IDMA_PERMIT[ 7] & ~reg_be))) |
               (addr_hit[ 8] & (|(ETH_IDMA_PERMIT[ 8] & ~reg_be))) |
               (addr_hit[ 9] & (|(ETH_IDMA_PERMIT[ 9] & ~reg_be))) |
               (addr_hit[10] & (|(ETH_IDMA_PERMIT[10] & ~reg_be))) |
               (addr_hit[11] & (|(ETH_IDMA_PERMIT[11] & ~reg_be))) |
               (addr_hit[12] & (|(ETH_IDMA_PERMIT[12] & ~reg_be))) |
               (addr_hit[13] & (|(ETH_IDMA_PERMIT[13] & ~reg_be))) |
               (addr_hit[14] & (|(ETH_IDMA_PERMIT[14] & ~reg_be))) |
               (addr_hit[15] & (|(ETH_IDMA_PERMIT[15] & ~reg_be))) |
               (addr_hit[16] & (|(ETH_IDMA_PERMIT[16] & ~reg_be))) |
               (addr_hit[17] & (|(ETH_IDMA_PERMIT[17] & ~reg_be))) |
               (addr_hit[18] & (|(ETH_IDMA_PERMIT[18] & ~reg_be))) |
               (addr_hit[19] & (|(ETH_IDMA_PERMIT[19] & ~reg_be)))));
  end

  assign low_addr_we = addr_hit[0] & reg_we & !reg_error;
  assign low_addr_wd = reg_wdata[31:0];

  assign machi_upper_addr_we = addr_hit[1] & reg_we & !reg_error;
  assign machi_upper_addr_wd = reg_wdata[15:0];

  assign machi_cooked_we = addr_hit[1] & reg_we & !reg_error;
  assign machi_cooked_wd = reg_wdata[16];

  assign machi_loopback_we = addr_hit[1] & reg_we & !reg_error;
  assign machi_loopback_wd = reg_wdata[17];

  assign machi_spare_we = addr_hit[1] & reg_we & !reg_error;
  assign machi_spare_wd = reg_wdata[21:18];

  assign machi_promiscuous_we = addr_hit[1] & reg_we & !reg_error;
  assign machi_promiscuous_wd = reg_wdata[22];

  assign machi_irq_en_we = addr_hit[1] & reg_we & !reg_error;
  assign machi_irq_en_wd = reg_wdata[23];

  assign mdio_mdio_clk_we = addr_hit[2] & reg_we & !reg_error;
  assign mdio_mdio_clk_wd = reg_wdata[0];

  assign mdio_mdio_o_we = addr_hit[2] & reg_we & !reg_error;
  assign mdio_mdio_o_wd = reg_wdata[1];

  assign mdio_mdio_oe_we = addr_hit[2] & reg_we & !reg_error;
  assign mdio_mdio_oe_wd = reg_wdata[2];

  assign src_addr_low_we = addr_hit[7] & reg_we & !reg_error;
  assign src_addr_low_wd = reg_wdata[31:0];

  assign src_addr_high_we = addr_hit[8] & reg_we & !reg_error;
  assign src_addr_high_wd = reg_wdata[31:0];

  assign dst_addr_low_we = addr_hit[9] & reg_we & !reg_error;
  assign dst_addr_low_wd = reg_wdata[31:0];

  assign dst_addr_high_we = addr_hit[10] & reg_we & !reg_error;
  assign dst_addr_high_wd = reg_wdata[31:0];

  assign length_low_we = addr_hit[11] & reg_we & !reg_error;
  assign length_low_wd = reg_wdata[31:0];

  assign length_high_we = addr_hit[12] & reg_we & !reg_error;
  assign length_high_wd = reg_wdata[31:0];

  assign conf_decouple_aw_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_decouple_aw_wd = reg_wdata[0];

  assign conf_decouple_rw_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_decouple_rw_wd = reg_wdata[1];

  assign conf_src_reduce_len_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_src_reduce_len_wd = reg_wdata[2];

  assign conf_dst_reduce_len_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_dst_reduce_len_wd = reg_wdata[3];

  assign conf_src_max_llen_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_src_max_llen_wd = reg_wdata[6:4];

  assign conf_dst_max_llen_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_dst_max_llen_wd = reg_wdata[9:7];

  assign conf_enable_nd_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_enable_nd_wd = reg_wdata[10];

  assign conf_src_protocol_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_src_protocol_wd = reg_wdata[13:11];

  assign conf_dst_protocol_we = addr_hit[13] & reg_we & !reg_error;
  assign conf_dst_protocol_wd = reg_wdata[16:14];

  assign req_valid_we = addr_hit[14] & reg_we & !reg_error;
  assign req_valid_wd = reg_wdata[0];

  assign rx_end_clr_we = addr_hit[18] & reg_we & !reg_error;
  assign rx_end_clr_wd = reg_wdata[0];

  assign rsp_valid_clr_we = addr_hit[19] & reg_we & !reg_error;
  assign rsp_valid_clr_wd = reg_wdata[0];

  // Read data return
  always_comb begin
    reg_rdata_next = '0;
    unique case (1'b1)
      addr_hit[0]: begin
        reg_rdata_next[31:0] = low_addr_qs;
      end

      addr_hit[1]: begin
        reg_rdata_next[15:0] = machi_upper_addr_qs;
        reg_rdata_next[16] = machi_cooked_qs;
        reg_rdata_next[17] = machi_loopback_qs;
        reg_rdata_next[21:18] = machi_spare_qs;
        reg_rdata_next[22] = machi_promiscuous_qs;
        reg_rdata_next[23] = machi_irq_en_qs;
      end

      addr_hit[2]: begin
        reg_rdata_next[0] = mdio_mdio_clk_qs;
        reg_rdata_next[1] = mdio_mdio_o_qs;
        reg_rdata_next[2] = mdio_mdio_oe_qs;
        reg_rdata_next[3] = mdio_mdio_i_qs;
      end

      addr_hit[3]: begin
        reg_rdata_next[0] = tx_busy_qs;
      end

      addr_hit[4]: begin
        reg_rdata_next[31:0] = tx_fcs_qs;
      end

      addr_hit[5]: begin
        reg_rdata_next[31:0] = rx_fcs_qs;
      end

      addr_hit[6]: begin
        reg_rdata_next[0] = rsr_rx_complete_qs;
        reg_rdata_next[1] = rsr_rx_irq_qs;
      end

      addr_hit[7]: begin
        reg_rdata_next[31:0] = src_addr_low_qs;
      end

      addr_hit[8]: begin
        reg_rdata_next[31:0] = src_addr_high_qs;
      end

      addr_hit[9]: begin
        reg_rdata_next[31:0] = dst_addr_low_qs;
      end

      addr_hit[10]: begin
        reg_rdata_next[31:0] = dst_addr_high_qs;
      end

      addr_hit[11]: begin
        reg_rdata_next[31:0] = length_low_qs;
      end

      addr_hit[12]: begin
        reg_rdata_next[31:0] = length_high_qs;
      end

      addr_hit[13]: begin
        reg_rdata_next[0] = conf_decouple_aw_qs;
        reg_rdata_next[1] = conf_decouple_rw_qs;
        reg_rdata_next[2] = conf_src_reduce_len_qs;
        reg_rdata_next[3] = conf_dst_reduce_len_qs;
        reg_rdata_next[6:4] = conf_src_max_llen_qs;
        reg_rdata_next[9:7] = conf_dst_max_llen_qs;
        reg_rdata_next[10] = conf_enable_nd_qs;
        reg_rdata_next[13:11] = conf_src_protocol_qs;
        reg_rdata_next[16:14] = conf_dst_protocol_qs;
      end

      addr_hit[14]: begin
        reg_rdata_next[0] = req_valid_qs;
      end

      addr_hit[15]: begin
        reg_rdata_next[0] = req_ready_qs;
      end

      addr_hit[16]: begin
        reg_rdata_next[0] = rsp_ready_qs;
      end

      addr_hit[17]: begin
        reg_rdata_next[0] = rsp_valid_qs;
      end

      addr_hit[18]: begin
        reg_rdata_next[0] = '0;
      end

      addr_hit[19]: begin
        reg_rdata_next[0] = '0;
      end

      default: begin
        reg_rdata_next = '1;
      end
    endcase
  end

  // Unused signal tieoff

  // wdata / byte enable are not always fully used
  // add a blanket unused statement to handle lint waivers
  logic unused_wdata;
  logic unused_be;
  assign unused_wdata = ^reg_wdata;
  assign unused_be = ^reg_be;

  // Assertions for Register Interface
  `ASSERT(en2addrHit, (reg_we || reg_re) |-> $onehot0(addr_hit))

endmodule

module eth_idma_reg_top_intf
#(
  parameter int AW = 7,
  localparam int DW = 32
) (
  input logic clk_i,
  input logic rst_ni,
  REG_BUS.in  regbus_slave,
  // To HW
  output eth_idma_reg_pkg::eth_idma_reg2hw_t reg2hw, // Write
  input  eth_idma_reg_pkg::eth_idma_hw2reg_t hw2reg, // Read
  // Config
  input devmode_i // If 1, explicit error return for unmapped register access
);
 localparam int unsigned STRB_WIDTH = DW/8;

`include "register_interface/typedef.svh"
`include "register_interface/assign.svh"

  // Define structs for reg_bus
  typedef logic [AW-1:0] addr_t;
  typedef logic [DW-1:0] data_t;
  typedef logic [STRB_WIDTH-1:0] strb_t;
  `REG_BUS_TYPEDEF_ALL(reg_bus, addr_t, data_t, strb_t)

  reg_bus_req_t s_reg_req;
  reg_bus_rsp_t s_reg_rsp;
  
  // Assign SV interface to structs
  `REG_BUS_ASSIGN_TO_REQ(s_reg_req, regbus_slave)
  `REG_BUS_ASSIGN_FROM_RSP(regbus_slave, s_reg_rsp)

  

  eth_idma_reg_top #(
    .reg_req_t(reg_bus_req_t),
    .reg_rsp_t(reg_bus_rsp_t),
    .AW(AW)
  ) i_regs (
    .clk_i,
    .rst_ni,
    .reg_req_i(s_reg_req),
    .reg_rsp_o(s_reg_rsp),
    .reg2hw, // Write
    .hw2reg, // Read
    .devmode_i
  );
  
endmodule


